// Test cases
function testIsValidBrackets() {
    // Test cases with expected results
    const testCases = [
        { input: "", expected: true, description: "empty string" },
        { input: "abc", expected: true, description: "string with only ordinary characters" },
        { input: "()", expected: true, description: "simple parentheses" },
        { input: "[]", expected: true, description: "simple square brackets" },
        { input: "{}", expected: true, description: "simple curly braces" },
        { input: "()[]{}", expected: true, description: "multiple types of brackets" },
        { input: "( [ ] { } )", expected: true, description: "brackets with spaces" },
        { input: "(abc[def]{ghi})", expected: true, description: "brackets with text inside" },
        { input: "((()))", expected: true, description: "nested parentheses" },
        { input: "([{}])", expected: true, description: "deeply nested brackets" },
        { input: "([)]", expected: false, description: "crossed brackets" },
        { input: "(", expected: false, description: "unclosed opening bracket" },
        { input: ")", expected: false, description: "extra closing bracket" },
        { input: "({)}", expected: false, description: "mismatched brackets" },
        { input: null, expected: false, description: "null input" },
        { input: 123, expected: false, description: "number input" },
        { input: {}, expected: false, description: "object input" },
        { input: [], expected: false, description: "array input" },
        { input: "a(b[c]d{e}f)g", expected: true, description: "mixed brackets with text" },
        { input: "a(b[c]d{e)f}", expected: false, description: "unbalanced brackets with text" }
    ];

    // Run tests
    let passed = 0;
    let failed = 0;

    for (const testCase of testCases) {
        const result = isValidBrackets(testCase.input);
        if (result === testCase.expected) {
            passed++;
            console.log(`✓ PASS: ${testCase.description}`);
        } else {
            failed++;
            console.log(`✗ FAIL: ${testCase.description} - Expected ${testCase.expected}, got ${result}`);
        }
    }

    console.log(`\nTest Results: ${passed} passed, ${failed} failed`);
}

// Run the tests
testIsValidBrackets();
```

Complexity Analysis:
- Time Complexity: O(n) - We iterate through the string exactly once, where n is the length of the string. Each operation inside the loop (checking if a character is an opening/closing bracket, pushing/popping from the stack) is O(1).
- Space Complexity: O(n) - In the worst case, the stack could store all characters if they're all opening brackets (e.g., "(((...((((")). This gives us O(n) space complexity.

Boundary Cases Handling:
1. Empty string: Returns true (no brackets to match)
2. String with only ordinary characters: Returns true (no brackets to match)
3. Deeply nested brackets: Returns true if properly nested, false otherwise
4. Extra closing brackets: Returns false (stack would be empty when trying to pop)
5. Unclosed opening brackets: Returns false (stack would not be empty at the end)
6. Invalid input types: Returns false for non-string inputs (null, numbers, objects, arrays)

The function follows LIFO (Last-In-First-Out) stack logic by pushing opening brackets onto the stack and popping them when encountering closing brackets. The most recently opened bracket must be the first one closed.

I'll implement both iterative and recursive binary search functions that find the first occurrence of a target in a sorted array.

```js
/**
 * Performs an iterative binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number|string>} sorted - The sorted array to search (ascending order)
 * @param {number|string} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(1)
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Assumes the input array is sorted in ascending order
 * - Returns -1 if target is not found in the array
 */
function binarySearch(sorted, target) {
  if (!Array.isArray(sorted)) {
    throw new TypeError('Input must be an array');
  }

  let left = 0;
  let right = sorted.length - 1;
  let result = -1;

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
      result = mid;
      right = mid - 1; // Continue searching in the left half
    } else if (sorted[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;
}

/**
 * Performs a recursive binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number|string>} sorted - The sorted array to search (ascending order)
 * @param {number|string} target - The value to search for
 * @param {number} [left=0] - The left boundary of the search range (internal use)
 * @param {number} [right=sorted.length-1] - The right boundary of the search range (internal use)
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(log n) due to recursion stack
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Safe for null/undefined input (validation in function body)
 * - Assumes the input array is sorted in ascending order
 * - Returns -1 if target is not found in the array
 */
function binarySearchRecursive(sorted, target, left = 0, right = sorted.length - 1) {
  if (!Array.isArray(sorted)) {
    throw new TypeError('Input must be an array');
  }

  // Handle empty array case
  if (sorted.length === 0) {
    return -1;
  }

  // Validate parameters to ensure they're numbers
  if (typeof left !== 'number' || typeof right !== 'number') {
    throw new TypeError('Left and right parameters must be numbers');
  }

  if (left > right) {
    return -1;
  }

  const mid = left + Math.floor((right - left) / 2);

  if (sorted[mid] === target) {
    // Check if this is the first occurrence
    if (mid === 0 || sorted[mid - 1] < target) {
      return mid;
    }
    // Continue searching in the left half
    return binarySearchRecursive(sorted, target, left, mid - 1);
  } else if (sorted[mid] < target) {
    return binarySearchRecursive(sorted, target, mid + 1, right);
  } else {
    return binarySearchRecursive(sorted, target, left, mid - 1);
  }
}
```

### Explanation:

**Iterative Implementation:**
1. Uses a while loop to narrow down the search range
2. When the target is found, it continues searching to the left to find the first occurrence
3. Time complexity: O(log n) - halves the search space each iteration
4. Space complexity: O(1) - uses constant extra space

**Recursive Implementation:**
1. Uses recursion to implement the binary search
2. When the target is found, it checks if it's the first occurrence by looking at the previous element
3. If not the first occurrence, it continues searching to the left
4. Time complexity: O(log n) - halves the search space each recursive call
5. Space complexity: O(log n) - due to recursion stack

**Boundary Cases:**
- Empty array: Returns -1
- Single element array: Returns 0 if the element matches, otherwise -1
- Target not found: Returns -1
- Duplicates: Returns the index of the first occurrence
- Null/undefined input: Throws TypeError (handled in function body)

**Input Requirements:**
- The input array must be sorted in ascending order
- The function does not modify the input array
- The function works with both numbers and strings

Both implementations use the safe midpoint calculation: `left + Math.floor((right - left) / 2)` to avoid potential overflow issues.

